def _modification_charge(tag: TagBase) -> int:
    '''Get the intrinsic (local) charge carried by a modification tag.

    Local charges are defined by the ProForma charged-formula notation and
    contribute to the total charge of the peptidoform ion in addition to any
    global charge state.
    '''
    mod = tag.find_modification() if hasattr(tag, 'find_modification') else None
    if mod is None:
        return 0
    if not isinstance(mod, (FormulaModification, GlycanModification)):
        return 0
    try:
        charge = mod.charge
    except Exception:
        return 0
    if charge is None:
        return 0
    return int(charge)


class UnimodModification(ModificationBase):

def _total_local_charge(self) -> int:
    """Sum the intrinsic charges of all localized charged formulas.

    ProForma distinguishes the global charge state after the peptidoform
    definition from local charges written as part of ``Formula`` (and
    charged glycan) modifications.  The ion's total charge is the sum of
    both (ProForma section 11.5).
    """
    total = 0
    fixed_modifications = self.properties['fixed_modifications']

    n_term_v = 0
    c_term_v = len(self) - 1
    for i, position in enumerate(self.sequence):
        aa = position[0].upper()
        n_term = i == n_term_v
        c_term = i == c_term_v
        for rule in fixed_modifications:
            if rule.is_valid(aa, n_term, c_term):
                total += _modification_charge(rule.modification_tag)
        tags = position[1]
        if tags:
            for tag in tags:
                total += _modification_charge(tag)
    for mod in self.properties['labile_modifications']:
        total += _modification_charge(mod)
    for mod in self.properties['unlocalized_modifications']:
        total += _modification_charge(mod)
    for mod in (self.properties.get('n_term') or []):
        total += _modification_charge(mod)
    for mod in (self.properties.get('c_term') or []):
        total += _modification_charge(mod)
    for iv in self.properties['intervals']:
        for tag in (iv.tags or []):
            total += _modification_charge(tag)
    return total

def mz(self, charge: Union[int, ChargeState, None] = None, **kwargs) -> float:
    """
    Compute the *total* m/z of the peptidoform in the specified charge state, or fall back
    to the peptidoform ion's defined charge state and adduction.

    This method first tries to get the composition of the peptidoform ion with :meth:`composition`
    and then forwards ``kwargs`` to :meth:`Composition.mass` to compute m/z with full flexibility,
    but if that fails due to missing modification compositions, this method falls back to directly
    computing monoisotopic mass and uses the charge state to get the m/z.

    .. warning::
        If no charge state of any kind is available, this will raise a :py:class:`MissingChargeStateError`.

    Parameters
    ----------
    charge : int or :class:`ChargeState`, optional
        The charge state either as in integer number of protons gained/lost,
        or a :class:`ChargeState` instance. If not provided, :attr:`charge_state`
        will be used.
    **kwargs :
        Forwarded to :meth:`Composition.mass`

    Returns
    -------
    float
    """
    charge_state = charge
    if charge_state is None:
        charge_state = self.charge_state
    elif isinstance(charge_state, Integral):
        charge_state = ChargeState(int(charge_state))
    elif not isinstance(charge_state, ChargeState):
        raise TypeError(
            f"Expected a charge state-like type, got {type(charge_state)}"
        )

    local_charge = self._total_local_charge()
    if charge_state is None and local_charge == 0:
        raise MissingChargeStateError(
            f"Requested an m/z value without providing a charge state and the peptidoform {self!r} does "
            "not have a charge state itself."
        )
    total_charge = (charge_state.charge if charge_state is not None else 0) + local_charge
    if total_charge == 0:
        raise MissingChargeStateError(
            f"Cannot compute an m/z value for {self!r}: the total ion charge is zero."
        )

    try:
        composition = self.composition(
            include_charge=charge_state, ignore_missing=False
        )
        mass_kwargs = dict(kwargs)
        mass_kwargs['charge'] = 0
        ion_mass = composition.mass(**mass_kwargs)
    except ProFormaError:
        if charge_state is None:
            charge_carrier_mass = 0.0
        else:
            charge_carrier_mass, _ = charge_state.for_mz_calculation()
        ion_mass = self.mass + charge_carrier_mass
    return ion_mass / abs(total_charge)

